function specialTable(d,key){let arr=d[key]||[];if(key==="inventory")return `<h3>Inventario tecnológico</h3><table class="table"><thead><tr><th>Equipo</th><th>Serial</th><th>Cant.</th><th>Estado</th><th>Sede destino</th><th>Guía</th></tr></thead><tbody>${arr.map(x=>`<tr><td>${x.tipoEquipo} ${esc(x.modelo)}</td><td>${esc(x.serialInv)}</td><td>${x.cantidad}</td><td>${x.estadoTec}</td><td>${esc(x.sedeDestino)}</td><td>${esc(x.guia)}</td></tr>`).join("")||"<tr><td colspan=6>Sin registros.</td></tr>"}</tbody></table>`;
if(key==="gestiones")return `<h3>Tablero de gestiones</h3><table class="table"><thead><tr><th>Gestión</th><th>Responsable</th><th>Prioridad</th><th>Estado</th><th>Compromiso</th></tr></thead><tbody>${arr.map(x=>`<tr><td>${esc(x.gestion)}</td><td>${esc(x.responsable)}</td><td>${x.prioridad}</td><td>${x.estado}</td><td>${x.compromiso}</td></tr>`).join("")||"<tr><td colspan=5>Sin registros.</td></tr>"}</tbody></table>`;
if(key==="resolved")return `<h3>Casos resueltos</h3><table class="table"><thead><tr><th>Caso</th><th>Cliente</th><th>Sede</th><th>Medio</th><th>Proveedor</th><th>Fecha</th><th>Solución</th></tr></thead><tbody>${arr.map(x=>`<tr><td>${esc(x.caso)}</td><td>${esc(x.clienteRes)}</td><td>${esc(x.sedeNombre||x.sedeRes)}</td><td>${esc(x.medio)}</td><td>${esc(x.provRes)}</td><td>${esc(x.fechaRes)}</td><td>${esc(x.solucion)}</td></tr>`).join("")||"<tr><td colspan=7>Sin registros.</td></tr>"}</tbody></table>`;
if(key==="crypto")return `<h3>Control técnico Crypto Pro</h3><table class="table"><thead><tr><th>Sede</th><th>Elemento</th><th>Cantidad</th><th>Resultado</th></tr></thead><tbody>${arr.map(x=>`<tr><td>${esc(x.sedeCrypto)}</td><td>${x.elemento}</td><td>${x.cantidadCrypto}</td><td>${x.resultadoCrypto}</td></tr>`).join("")||"<tr><td colspan=4>Sin registros.</td></tr>"}</tbody></table>`;
return `<h3>Registros</h3><table class="table"><thead><tr><th>Cliente</th><th>Ciudad</th><th>Tipo</th><th>Solicitud</th><th>Entrega</th></tr></thead><tbody>${arr.map(x=>`<tr><td>${esc(x.cliente)}</td><td>${esc(x.ciudad)}</td><td>${x.tipo}</td><td>${esc(x.desc)}</td><td>${x.fe||""}</td></tr>`).join("")||"<tr><td colspan=5>Sin registros.</td></tr>"}</tbody></table>`}

function visitors(c){let d=db();c.innerHTML=`<div class="page-head"><div><h2>Visitantes</h2></div></div><div class="card"><div class="form-grid">${["ciudad","cliente","oficina","nombres","apellidos","cedula","cargo","entrada","salida","motivo"].map(k=>field(label(k),k,k==="entrada"||k==="salida"?"datetime-local":"text")).join("")}</div><div class="actions"><button class="primary" id="saveVisitor">Guardar visitante</button><button class="secondary" onclick="exportCSV('visitors')">Descargar Excel</button></div></div><div class="card table-wrap" style="margin-top:14px"><table class="table"><thead><tr><th>Nombre</th><th>Cédula</th><th>Cliente</th><th>Oficina</th><th>Entrada</th><th>Salida</th></tr></thead><tbody>${d.visitors.map(x=>`<tr><td>${esc(x.nombres+" "+x.apellidos)}</td><td>${esc(x.cedula)}</td><td>${esc(x.cliente)}</td><td>${esc(x.oficina)}</td><td>${x.entrada}</td><td>${x.salida}</td></tr>`).join("")||"<tr><td colspan=6>Sin registros.</td></tr>"}</tbody></table></div>`;$("#saveVisitor").onclick=()=>{let x={};["ciudad","cliente","oficina","nombres","apellidos","cedula","cargo","entrada","salida","motivo"].forEach(k=>x[k]=$("#"+k).value);d.visitors.push(x);save(STORE,d);page(tab)}}
function dashboard(c){
 let d=db(),by=o=>d.tickets.filter(t=>t.origen===o).length;
 const dates=[...new Set(d.cctvReports.map(x=>x.date))].sort().reverse();
 const selected=dates[0]||new Date().toISOString().slice(0,10);
 const clients=["EPAGO","DOMESA","PYC"];
 const pctFor=(client,date)=>{let rows=d.cctvReports.filter(x=>x.date===date&&x.cliente===client);let total=rows.length,ok=rows.filter(x=>x.status==="connected").length;return total?Math.round(ok/total*100):0};
 const daily=dates.slice(0,14).map(date=>({date,epago:pctFor("EPAGO",date),domesa:pctFor("DOMESA",date),pyc:pctFor("PYC",date)}));
 c.innerHTML=`<div class="page-head"><div><h2>Indicadores</h2><div class="muted">Consolidado operativo y conexión CCTV por día.</div></div></div>
 <div class="grid"><div class="card span3"><div>Total tickets</div><div class="kpi">${d.tickets.length}</div></div><div class="card span3"><div>SMS</div><div class="kpi">${by("SMS")}</div></div><div class="card span3"><div>Correo</div><div class="kpi">${by("Correo")}</div></div><div class="card span3"><div>Inspección</div><div class="kpi">${by("Inspección")}</div></div>
 <div class="card span12"><h3>Conexión CCTV del último día registrado</h3><div class="muted">${selected?formatDate(selected):"Aún no hay registros diarios"}</div><div class="cctv-kpis">
 ${clients.map(cl=>`<div class="cctv-kpi"><div class="cctv-kpi-name">${cl}</div><div class="cctv-ring" style="--pct:${pctFor(cl,selected)}%"><div class="cctv-ring-value">${pctFor(cl,selected)}%</div></div><div class="muted">${d.cctvReports.filter(x=>x.date===selected&&x.cliente===cl).length} cámaras registradas</div></div>`).join("")}</div></div>
 <div class="card span12"><h3>Comportamiento diario de conexión CCTV</h3>${daily.length?`<div class="cctv-history">${daily.map(x=>`<div class="cctv-day"><div class="cctv-day-date">${formatDate(x.date)}</div><div><b>ePago</b><div class="bar"><span style="width:${x.epago}%"></span></div><small>${x.epago}%</small></div><div><b>Domesa</b><div class="bar"><span style="width:${x.domesa}%"></span></div><small>${x.domesa}%</small></div><div><b>PYC</b><div class="bar"><span style="width:${x.pyc}%"></span></div><small>${x.pyc}%</small></div></div>`).join("")}</div>`:`<p class="muted">Todavía no hay registros. Diligencie el reporte CCTV para comenzar el histórico diario.</p>`}</div>
 <div class="card span6"><h3>Escalados por proveedor</h3><p>Rediseg: ${d.tickets.filter(t=>t.proveedor==="Rediseg").length}</p><p>Formatec: ${d.tickets.filter(t=>t.proveedor==="Formatec").length}</p></div><div class="card span6"><h3>Resueltos registrados</h3><p>${d.resolved.length}</p></div></div>`
}
function formatDate(v){if(!v)return "";const [y,m,day]=v.split("-");return `${day}/${m}/${y}`}
function cctvReport(c){
 let d=db();
 const clients=["EPAGO","DOMESA","PYC"];
 const today=new Date().toISOString().slice(0,10);
 c.innerHTML=`<div class="page-head"><div><h2>Reporte de conexión CCTV</h2><div class="muted">Diligencie diariamente el estado de cada cámara por sede. El porcentaje se calcula automáticamente para el Dashboard.</div></div></div>
 <div class="card"><div class="form-grid"><div class="field"><label>Fecha del reporte</label><input id="cctvDate" type="date" value="${today}"></div><div class="field"><label>Cliente</label><select id="cctvClient"><option value="">Seleccione...</option>${clients.map(x=>`<option>${x}</option>`).join("")}</select></div><div class="field"><label>Sede</label><select id="cctvSite"><option value="">Seleccione cliente primero...</option></select></div><div class="field"><label>Número de cámaras a revisar</label><input id="cameraCount" type="number" min="1" max="256" value="16"></div></div><div class="actions"><button class="primary" id="loadCameras">Cargar cámaras</button></div></div>
 <div class="card" id="cameraPanel" style="margin-top:14px"><h3>Estado de cámaras</h3><p class="muted">Seleccione cliente, sede y número de cámaras y pulse “Cargar cámaras”.</p></div>
 <div class="card table-wrap" style="margin-top:14px"><h3>Histórico diario</h3><table class="table"><thead><tr><th>Fecha</th><th>Cliente</th><th>Sede</th><th>Conectadas</th><th>No conectadas</th><th>% conexión</th><th>Registrado por</th></tr></thead><tbody>${buildCctvHistory(d.cctvReports)}</tbody></table></div>`;
 const clientSel=$("#cctvClient"),siteSel=$("#cctvSite"),count=$("#cameraCount");
 clientSel.onchange=()=>{let sites=d.offices.filter(o=>o.cliente===clientSel.value&&!/eliminada|desmonte/i.test(o.status||""));siteSel.innerHTML='<option value="">Seleccione...</option>'+sites.map(o=>`<option value="${esc(o.codigo)}">${esc(o.oficina)} (${esc(o.codigo)})</option>`).join("");let first=sites[0];if(first)count.value=Math.min(256,Math.max(1,Number(first.canales)||16));};
 $("#loadCameras").onclick=()=>{let site=d.offices.find(o=>o.codigo===siteSel.value);let masterCams=Array.isArray(site?.camaras)?site.camaras:[];let n=Math.max(1,Math.min(256,masterCams.length||parseInt(count.value||site?.canales||16,10)));if(!site)return toast("Seleccione una sede");let existing=d.cctvReports.filter(x=>x.date===$("#cctvDate").value&&x.cliente===clientSel.value&&x.codigo===site.codigo);let old=existing.reduce((a,x)=>(a[x.camera]=x,a),{});$("#cameraPanel").innerHTML=`<div class="cctv-panel-head"><div><h3>${esc(site.oficina)}</h3><div class="muted">${esc(clientSel.value)} · ${n} cámaras · ${formatDate($("#cctvDate").value)}</div></div><div class="cctv-summary" id="cctvSummary">0% conexión</div></div><div class="site-info-strip"><span><b>Dirección:</b> ${esc(site.direccion)}</span><span><b>Ciudad:</b> ${esc(site.ciudad)}</span><span><b>IP:</b> ${esc(site.ip)}</span><span><b>Serial:</b> ${esc(site.serial)}</span><span><b>PONAL:</b> ${esc(site.ponal)}</span><span><b>Coordinador:</b> ${esc(site.coordinador?.nombre||"")} · ${esc(site.coordinador?.celular||"")}</span><span><b>Regional:</b> ${esc(site.regionalContacto?.nombre||"")}</span></div><div class="camera-grid">${Array.from({length:n},(_,i)=>{let cam=i+1,master=masterCams[i]||{numero:cam},prev=old[cam],st=prev?.status||"connected";return `<div class="camera-row"><div class="camera-id"><b>Cámara ${esc(master.numero||cam)}</b><small>${esc(master.etiqueta||"Sin etiqueta")} · DVR/NVR ${esc(master.dvr||"-")}</small></div><select class="camera-status" data-camera="${cam}"><option value="connected" ${st==="connected"?"selected":""}>🟢 Conectada</option><option value="disconnected" ${st==="disconnected"?"selected":""}>🔴 No conectada</option></select><input class="camera-note" data-camera-note="${cam}" value="${esc(prev?.note||"")}" placeholder="Observación opcional"></div>`}).join("")}</div><div class="actions"><button class="primary" id="saveCctv">Guardar reporte diario</button></div>`;updateCctvSummary();$("#saveCctv").onclick=saveCctvReport;document.querySelectorAll(".camera-status").forEach(e=>e.onchange=updateCctvSummary)};
 function updateCctvSummary(){let els=[...document.querySelectorAll(".camera-status")];if(!els.length)return;let ok=els.filter(x=>x.value==="connected").length;$("#cctvSummary").textContent=`${Math.round(ok/els.length*100)}% conexión · ${ok}/${els.length}`}
 function saveCctvReport(){let date=$("#cctvDate").value,site=d.offices.find(o=>o.codigo===siteSel.value);let els=[...document.querySelectorAll(".camera-status")];if(!date||!site||!els.length)return toast("Complete fecha, cliente, sede y cámaras");d.cctvReports=d.cctvReports.filter(x=>!(x.date===date&&x.codigo===site.codigo));els.forEach(e=>{let cam=Number(e.dataset.camera),note=document.querySelector(`[data-camera-note="${cam}"]`)?.value||"";let master=Array.isArray(site.camaras)?site.camaras[cam-1]:null;d.cctvReports.push({date,cliente:clientSel.value,codigo:site.codigo,oficina:site.oficina,camera:cam,cameraNumber:master?.numero||String(cam),cameraLabel:master?.etiqueta||"",dvr:master?.dvr||"",status:e.value,note,registeredBy:current.username,registeredAt:new Date().toISOString()})});save(STORE,d);toast("Reporte CCTV guardado correctamente");cctvReport(c)}
}
function buildCctvHistory(arr){let groups={};arr.forEach(x=>{let k=x.date+"|"+x.cliente+"|"+x.codigo;(groups[k]??=[]).push(x)});let rows=Object.values(groups).sort((a,b)=>(b[0].date||"").localeCompare(a[0].date||"")).map(g=>{let ok=g.filter(x=>x.status==="connected").length,total=g.length,pct=Math.round(ok/total*100);return `<tr><td>${formatDate(g[0].date)}</td><td>${esc(g[0].cliente)}</td><td>${esc(g[0].oficina)}</td><td>${ok}</td><td>${total-ok}</td><td><b>${pct}%</b></td><td>${esc(g[0].registeredBy||"")}</td></tr>`}).join("");return rows||`<tr><td colspan="7">Sin reportes registrados.</td></tr>`}

function userApprovals(c){
 if(!current.mainAdmin){c.innerHTML=`<div class="card"><h2>Acceso restringido</h2><p>Solo el administrador principal puede aprobar usuarios.</p></div>`;return}
 let u=users(), pending=u.filter(x=>x.status==="pending"), active=u.filter(x=>x.status==="active"), rejected=u.filter(x=>x.status==="rejected");
 c.innerHTML=`<div class="page-head"><div><h2>Solicitudes de usuarios</h2><div class="muted">Un solo administrador principal controla las altas de SYRUEN.</div></div></div>
 <div class="grid"><div class="card span4"><div>Pendientes</div><div class="kpi">${pending.length}</div></div><div class="card span4"><div>Activos</div><div class="kpi">${active.length}</div></div><div class="card span4"><div>No aprobados</div><div class="kpi">${rejected.length}</div></div></div>
 <div class="card table-wrap"><h3>Solicitudes pendientes</h3><table class="table"><thead><tr><th>Usuario</th><th>Nombre</th><th>Perfil</th><th>Correo</th><th>Fecha</th><th>Acciones</th></tr></thead><tbody>${pending.map(x=>`<tr><td>${esc(x.username)}</td><td>${esc(x.name)}</td><td>${esc(roles[x.role]?.name||x.role)}</td><td>${esc(x.email)}</td><td>${x.requestedAt?new Date(x.requestedAt).toLocaleString("es-CO"):""}</td><td><button class="primary small" onclick="approveUser('${esc(x.username)}')">Aprobar</button> <button class="danger small" onclick="rejectUser('${esc(x.username)}')">Rechazar</button></td></tr>`).join("")||`<tr><td colspan="6">No hay solicitudes pendientes.</td></tr>`}</tbody></table></div>
 <div class="card table-wrap" style="margin-top:14px"><h3>Usuarios registrados</h3><table class="table"><thead><tr><th>Usuario</th><th>Nombre</th><th>Perfil</th><th>Correo</th><th>Estado</th></tr></thead><tbody>${u.map(x=>`<tr><td>${esc(x.username)}</td><td>${esc(x.name)}</td><td>${esc(roles[x.role]?.name||x.role)}</td><td>${esc(x.email)}</td><td>${x.mainAdmin?"Administrador principal":x.status}</td></tr>`).join("")}</tbody></table></div>`;
}
window.approveUser=username=>{let u=users(),x=u.find(v=>v.username===username);if(!x)return;if(!confirm(`¿Aprobar a ${x.name} (${x.username})?`))return;x.status="active";x.approvedAt=new Date().toISOString();x.approvedBy=current.username;save(USERS,u);notifyUser(x,"approved");userApprovals($("#content"));toast("Usuario aprobado. Se registró la notificación de aprobación.")};
window.rejectUser=username=>{let u=users(),x=u.find(v=>v.username===username);if(!x)return;let reason=prompt("Motivo del rechazo (opcional):","");if(reason===null)return;x.status="rejected";x.rejectedAt=new Date().toISOString();x.rejectedBy=current.username;x.rejectionReason=reason;save(USERS,u);notifyUser(x,"rejected",reason);userApprovals($("#content"));toast("Usuario rechazado. Se registró la notificación.")};
function notifyUser(x,type,reason=""){let d=db();d.userNotifications.push({id:"NOT-"+Date.now(),username:x.username,email:x.email,type,reason,createdAt:new Date().toISOString(),read:false});save(STORE,d)}

function exportCSV(key){let a=db()[key]||[],keys=[...new Set(a.flatMap(x=>Object.keys(x)))],csv=[keys.join(","),...a.map(x=>keys.map(k=>`"${String(x[k]??"").replaceAll('"','""')}"`).join(","))].join("\n"),blob=new Blob(["\ufeff"+csv],{type:"text/csv;charset=utf-8"}),u=URL.createObjectURL(blob),a1=document.createElement("a");a1.href=u;a1.download=key+".csv";a1.click();URL.revokeObjectURL(u)}
function label(x){return x.replace(/([A-Z])/g," $1").replace(/^./,m=>m.toUpperCase()).replace("Ip","IP").replace("Sim","N. SIM").replace("Pon al","PONAL").replace("Dvrs","DVR/NVR").replace("Cli","Cliente").replace("Fs","Fecha solicitud").replace("Fe","Fecha entrega").replace("Desc","Descripción")}
function esc(v){return String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]))}
function toast(m){let e=document.createElement("div");e.className="toast";e.textContent=m;document.body.appendChild(e);setTimeout(()=>e.remove(),2600)}
(function(){let s=sessionStorage.getItem(sessionKey);if(s){try{current=JSON.parse(s);tab=roles[current.role].tabs[0][0];render()}catch{sessionStorage.removeItem(sessionKey);splash()}}else splash()})()
